class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'

function parseLine(line, st) {
  let i = 0
  const n = line.length
  const skip = () => { while (i < n && isWs(line[i])) i++ }
  const atEnd = () => i >= n || line[i] === '#' || line[i] === ';'

  function parseString(q) {
    i++
    let out = ''
    for (;;) {
      if (i >= n) fail('unterminated string')
      const c = line[i]
      if (c === q) { i++; return out }
      if (q === '"' && c === '\\') {
        i++
        if (i >= n) fail('unterminated string')
        const e = line[i]
        const cp = String.fromCodePoint(line.codePointAt(i))
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = line.slice(i + 1, i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          i += 4
        } else fail('invalid escape \\' + cp)
        i += e === 'u' ? 1 : cp.length
        continue
      }
      out += c
      i++
    }
  }

  function parseName() {
    if (i < n && (line[i] === '"' || line[i] === "'")) return parseString(line[i])
    const s = i
    while (i < n && /[A-Za-z0-9_-]/.test(line[i])) i++
    if (i === s) fail('expected a name')
    return line.slice(s, i)
  }

  function parseDotted() {
    const parts = [parseName()]
    for (;;) {
      const save = i
      skip()
      if (i < n && line[i] === '.') {
        i++
        skip()
        parts.push(parseName())
      } else { i = save; return parts }
    }
  }

  function parseValue() {
    if (atEnd() || line[i] === ',' || line[i] === ']' || line[i] === '}') fail('expected a value')
    const c = line[i]
    if (c === '"' || c === "'") return { t: 'string', v: parseString(c) }
    if (c === '[') {
      i++
      const items = []
      skip()
      if (i < n && line[i] === ']') { i++; return { t: 'array', items, aot: false } }
      for (;;) {
        skip()
        items.push(parseValue())
        skip()
        if (i < n && line[i] === ',') {
          i++
          skip()
          if (i < n && line[i] === ']') { i++; break }
          if (atEnd()) fail('unterminated array')
          continue
        }
        if (i < n && line[i] === ']') { i++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      i++
      const tbl = newTable()
      skip()
      if (i < n && line[i] === '}') { i++; return tbl }
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated inline table')
        const parts = parseDotted()
        skip()
        if (!(i < n && line[i] === '=')) fail('expected = in an inline table')
        i++
        skip()
        const v = parseValue()
        assign(tbl, [], parts, v)
        skip()
        if (i < n && line[i] === ',') { i++; skip(); if (atEnd()) fail('unterminated inline table'); continue }
        if (i < n && line[i] === '}') { i++; break }
        fail('unterminated inline table')
      }
      return tbl
    }
    const s = i
    while (i < n && !isWs(line[i]) && line[i] !== ',' && line[i] !== ']' && line[i] !== '}') i++
    const tok = line.slice(s, i)
    if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
    if (/^[+-]?\d+(_\d+)*$/.test(tok)) {
      return { t: 'integer', v: BigInt(tok.replace(/_/g, '')).toString() }
    }
    if (/^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/.test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    fail('invalid value ' + tok)
  }

  // walk the intermediate parts of a dotted path from `base`, creating tables
  function walk(base, prefix, parts) {
    let cur = base
    const path = [...prefix]
    for (const p of parts) {
      path.push(p)
      let nx = cur.map.get(p)
      if (nx === undefined) { nx = newTable(); cur.map.set(p, nx) }
      if (nx.t === 'table') cur = nx
      else if (nx.t === 'array' && nx.aot) cur = nx.items[nx.items.length - 1]
      else fail(path.join('.') + ' is not a table')
    }
    return cur
  }

  function assign(base, prefix, parts, v) {
    const cur = walk(base, prefix, parts.slice(0, -1))
    const last = parts[parts.length - 1]
    if (cur.map.has(last)) fail('key ' + [...prefix, ...parts].join('.') + ' is defined twice')
    cur.map.set(last, v)
  }

  skip()
  if (atEnd()) return
  if (line[i] === '[') {
    const dbl = line[i + 1] === '['
    i += dbl ? 2 : 1
    skip()
    const parts = parseDotted()
    skip()
    for (let k = 0; k < (dbl ? 2 : 1); k++) {
      if (!(i < n && line[i] === ']')) fail('unterminated table header')
      i++
    }
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    const cur = walk(st.root, [], parts.slice(0, -1))
    const last = parts[parts.length - 1]
    const full = parts.join('.')
    const ex = cur.map.get(last)
    if (dbl) {
      if (ex === undefined) {
        const t = newTable()
        cur.map.set(last, { t: 'array', items: [t], aot: true })
        st.cur = t
      } else if (ex.t === 'array' && ex.aot) {
        const t = newTable()
        ex.items.push(t)
        st.cur = t
      } else fail(full + ' is not an array of tables')
    } else if (ex === undefined) {
      const t = newTable()
      t.header = true
      cur.map.set(last, t)
      st.cur = t
    } else if (ex.t !== 'table') fail(full + ' is not a table')
    else if (ex.header) fail('table ' + full + ' is defined twice')
    else { ex.header = true; st.cur = ex }
    return
  }
  const parts = parseDotted()
  skip()
  if (!(i < n && line[i] === '=')) fail('expected key = value')
  i++
  skip()
  const v = parseValue()
  skip()
  if (!atEnd()) fail('trailing text after a value')
  assign(st.cur, [], parts, v)
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let k = 0; k < Math.min(x.length, y.length); k++) {
    const d = x[k].codePointAt(0) - y[k].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(v, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (v.t === 'table') {
    const ks = sortedKeys(v)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(v.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (v.t === 'array') {
    if (!v.items.length) return '[]'
    return '[\n' + v.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (v.t === 'string') return JSON.stringify(v.v)
  if (v.t === 'float') return JSON.stringify(v.v)
  return String(v.v)
}

function toKeys(v, path, out) {
  if (v.t === 'table') {
    for (const k of sortedKeys(v)) {
      const p = path === null ? k : path + '.' + k
      const c = v.map.get(k)
      out.push(p + ' ' + c.t)
      toKeys(c, p, out)
    }
  } else if (v.t === 'array') {
    v.items.forEach((c, idx) => {
      const p = path + '[' + idx + ']'
      out.push(p + ' ' + c.t)
      toKeys(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const st = { root: newTable() }
st.cur = st.root
for (let k = 0; k < lines.length; k++) {
  try {
    parseLine(lines[k], st)
  } catch (e) {
    if (!(e instanceof ParseError)) throw e
    process.stderr.write(`error: line ${k + 1}: ${e.message}\n`)
    process.exit(2)
  }
}
if (args[0] === 'json') process.stdout.write(toJson(st.root, 0) + '\n')
else {
  const out = []
  toKeys(st.root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

